CREATE   VIEW [synapse_fo].[vwDIRPARTYBASEENTITY]
AS
SELECT T1.PARTYNUMBER AS PARTYNUMBER
	,T1.NAME AS NAME
	,T1.NAMEALIAS AS NAMEALIAS
	,T1.KNOWNAS AS KNOWNAS
	,T1.ADDRESSBOOKNAMES AS ADDRESSBOOKS
	,T1.LANGUAGEID AS LANGUAGEID
	,T1.INSTANCERELATIONTYPE AS INSTANCERELATIONTYPE
	,T1.ABC AS ORGANIZATIONABCCODE
	,T1.NUMBEROFEMPLOYEES AS ORGANIZATIONNUMOFEMPLOYEES
	,T1.ORGNUMBER AS ORGANIZATIONNUMBER
	,T1.PHONETICNAME AS ORGANIZATIONPHONETICNAME
	,T1.INITIALS AS PERSONINITIALS
	,T1.PERSONALSUFFIX AS PERSONALSUFFIX
	,T1.PERSONALTITLE AS PERSONALTITLE
	,T1.PROFESSIONALTITLE AS PERSONPROFESSIONALTITLE
	,T1.PROFESSIONALSUFFIX AS PERSONPROFESSIONALSUFFIX
	,T1.PHONETICFIRSTNAME AS PERSONPHONETICFIRSTNAME
	,T1.PHONETICLASTNAME AS PERSONPHONETICLASTNAME
	,T1.PHONETICMIDDLENAME AS PERSONPHONETICMIDDLENAME
	,T1.GENDER AS PERSONGENDER
	,T1.MARITALSTATUS AS PERSONMARITALSTATUS
	,T1.HOBBIES AS PERSONHOBBIES
	,T1.CHILDRENNAMES AS PERSONCHILDRENNAMES
	,T1.ANNIVERSARYDAY AS PERSONANNIVERSARYDAY
	,T1.ANNIVERSARYMONTH AS PERSONANNIVERSARYMONTH
	,T1.ANNIVERSARYYEAR AS PERSONANNIVERSARYYEAR
	,T1.BIRTHDAY AS PERSONBIRTHDAY
	,T1.BIRTHMONTH AS PERSONBIRTHMONTH
	,T1.BIRTHYEAR AS PERSONBIRTHYEAR
	,T1.DATAAREA AS LEGALENTITYDATAAREA
	,T1.ORGANIZATIONTYPE AS ORGANIZATIONTYPE
	,T1.OMOPERATINGUNITNUMBER AS OPERATINGUNITNUMBER
	,T1.OMOPERATINGUNITTYPE AS OPERATINGUNITTYPE
	,T1.DESCRIPTION AS TEAMDESCRIPTION
	,T1.TEAMMEMBERSHIPCRITERION AS TEAMMEMBERSHIPCRITERION
	,T1.PRIMARYADDRESSLOCATION AS PRIMARYADDRESSLOCATION
	,T1.NAMESEQUENCE AS NAMESEQUENCE
	,T1.RECID AS PARTYRECORDID
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.MODIFIEDBY AS MODIFIEDBY
	,T1.CREATEDDATETIME AS CREATEDDATETIME
	,T1.CREATEDBY AS CREATEDBY
	,T1.RECVERSION AS RECVERSION
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.RECID AS PRIMARYCONTACTEMAILRECORDID
	,T2.LOCATOR AS PRIMARYCONTACTEMAIL
	,T2.DESCRIPTION AS PRIMARYCONTACTEMAILDESCRIPTION
	,T2.ISINSTANTMESSAGE AS PRIMARYCONTACTEMAILISIM
	,T2.ELECTRONICADDRESSROLES AS PRIMARYCONTACTEMAILPURPOSE
	,T2.ISPRIVATE AS PRIMARYCONTACTEMAILISPRIVATE
	,T2.RECVERSION AS RECVERSION#2
	,T2.PARTITION AS PARTITION#2
	,T2.RECID AS RECID#2
	,T3.RECID AS PRIMARYCONTACTFAXRECORDID
	,T3.LOCATOR AS PRIMARYCONTACTFAX
	,T3.DESCRIPTION AS PRIMARYCONTACTFAXDESCRIPTION
	,T3.LOCATOREXTENSION AS PRIMARYCONTACTFAXEXTENSION
	,T3.ELECTRONICADDRESSROLES AS PRIMARYCONTACTFAXPURPOSE
	,T3.ISPRIVATE AS PRIMARYCONTACTFAXISPRIVATE
	,T3.RECVERSION AS RECVERSION#3
	,T3.PARTITION AS PARTITION#3
	,T3.RECID AS RECID#3
	,T4.RECID AS PRIMARYCONTACTPHONERECORDID
	,T4.LOCATOR AS PRIMARYCONTACTPHONE
	,T4.DESCRIPTION AS PRIMARYCONTACTPHONEDESCRIPTION
	,T4.LOCATOREXTENSION AS PRIMARYCONTACTPHONEEXTENSION
	,T4.ISMOBILEPHONE AS PRIMARYCONTACTPHONEISMOBILE
	,T4.ELECTRONICADDRESSROLES AS PRIMARYCONTACTPHONEPURPOSE
	,T4.ISPRIVATE AS PRIMARYCONTACTPHONEISPRIVATE
	,T4.RECVERSION AS RECVERSION#4
	,T4.PARTITION AS PARTITION#4
	,T4.RECID AS RECID#4
	,T5.RECID AS PRIMARYCONTACTTELEXRECORDID
	,T5.LOCATOR AS PRIMARYCONTACTTELEX
	,T5.DESCRIPTION AS PRIMARYCONTACTTELEXDESCRIPTION
	,T5.ELECTRONICADDRESSROLES AS PRIMARYCONTACTTELEXPURPOSE
	,T5.ISPRIVATE AS PRIMARYCONTACTTELEXISPRIVATE
	,T5.RECVERSION AS RECVERSION#5
	,T5.PARTITION AS PARTITION#5
	,T5.RECID AS RECID#5
	,T6.RECID AS PRIMARYCONTACTURLRECORDID
	,T6.LOCATOR AS PRIMARYCONTACTURL
	,T6.DESCRIPTION AS PRIMARYCONTACTURLDESCRIPTION
	,T6.ELECTRONICADDRESSROLES AS PRIMARYCONTACTURLPURPOSE
	,T6.ISPRIVATE AS PRIMARYCONTACTURLISPRIVATE
	,T6.RECVERSION AS RECVERSION#6
	,T6.PARTITION AS PARTITION#6
	,T6.RECID AS RECID#6
	,T7.RECID AS PRIMARYCONTACTFACEBOOKRECORDID
	,T7.LOCATOR AS PRIMARYCONTACTFACEBOOK
	,T7.DESCRIPTION AS PRIMARYCONTACTFACEBOOKDESCRIPTION
	,T7.ELECTRONICADDRESSROLES AS PRIMARYCONTACTFACEBOOKPURPOSE
	,T7.ISPRIVATE AS PRIMARYCONTACTFACEBOOKISPRIVATE
	,T7.RECVERSION AS RECVERSION#7
	,T7.PARTITION AS PARTITION#7
	,T7.RECID AS RECID#7
	,T8.RECID AS PRIMARYCONTACTTWITTERRECORDID
	,T8.LOCATOR AS PRIMARYCONTACTTWITTER
	,T8.DESCRIPTION AS PRIMARYCONTACTTWITTERDESCRIPTION
	,T8.ELECTRONICADDRESSROLES AS PRIMARYCONTACTTWITTERPURPOSE
	,T8.ISPRIVATE AS PRIMARYCONTACTTWITTERISPRIVATE
	,T8.RECVERSION AS RECVERSION#8
	,T8.PARTITION AS PARTITION#8
	,T8.RECID AS RECID#8
	,T9.RECID AS PRIMARYCONTACTLINKEDINRECORDID
	,T9.LOCATOR AS PRIMARYCONTACTLINKEDIN
	,T9.DESCRIPTION AS PRIMARYCONTACTLINKEDINDESCRIPTION
	,T9.ELECTRONICADDRESSROLES AS PRIMARYCONTACTLINKEDINPURPOSE
	,T9.ISPRIVATE AS PRIMARYCONTACTLINKEDINISPRIVATE
	,T9.RECVERSION AS RECVERSION#9
	,T9.PARTITION AS PARTITION#9
	,T9.RECID AS RECID#9
	,T10.RECVERSION AS RECVERSION#10
	,T10.PARTITION AS PARTITION#10
	,T10.RECID AS RECID#10
	,T11.POSTALADDRESSROLES AS ADDRESSLOCATIONROLES
	,T11.RECID AS DIRPARTYLOCATIONRECID
	,T11.RECVERSION AS RECVERSION#14
	,T11.PARTITION AS PARTITION#14
	,T11.RECID AS RECID#14
	,T12.RECVERSION AS RECVERSION#15
	,T12.PARTITION AS PARTITION#15
	,T12.RECID AS RECID#15
	,T13.AFFIX AS PERSONPERSONALSUFFIX
	,T13.RECVERSION AS RECVERSION#11
	,T13.PARTITION AS PARTITION#11
	,T13.RECID AS RECID#11
	,T14.AFFIX AS PERSONPERSONALTITLE
	,T14.RECVERSION AS RECVERSION#12
	,T14.PARTITION AS PARTITION#12
	,T14.RECID AS RECID#12
	,T15.FIRSTNAME AS PERSONFIRSTNAME
	,T15.MIDDLENAME AS PERSONMIDDLENAME
	,T15.LASTNAMEPREFIX AS PERSONLASTNAMEPREFIX
	,T15.LASTNAME AS PERSONLASTNAME
	,T15.VALIDTO AS PERSONNAMEVALIDTO
	,T15.VALIDFROM AS PERSONNAMEVALIDFROM
	,T15.RECID AS DIRPERSONNAMERECID
	,T15.RECVERSION AS RECVERSION#13
	,T15.PARTITION AS PARTITION#13
	,T15.RECID AS RECID#13
	,T16.DUNSNUMBER AS DUNSNUMBER
	,T16.RECVERSION AS RECVERSION#16
	,T16.PARTITION AS PARTITION#16
	,T16.RECID AS RECID#16
	,(
		CAST((
				CASE T1.INSTANCERELATIONTYPE
					WHEN 10643
						THEN 'Person'
					WHEN 11000
						THEN 'OperatingUnit'
					WHEN 1209
						THEN 'Organization'
					WHEN 17209
						THEN 'Team'
					WHEN 6105
						THEN 'LegalEntity'
					ELSE ''
					END
				) AS NVARCHAR(13))
		) AS PARTYTYPE
	,(
		CAST((
				CASE T1.OMOperatingUnitType
					WHEN 1
						THEN 'Department'
					WHEN 2
						THEN 'CostCenter'
					WHEN 3
						THEN 'ValueStream'
					WHEN 4
						THEN 'BusinessUnit'
					WHEN 6
						THEN 'RetailChannel'
					WHEN 7
						THEN 'Branch'
					WHEN 8
						THEN 'RentalLocation'
					WHEN 9
						THEN 'Region'
					ELSE ''
					END
				) AS NVARCHAR(60))
		) AS OPERATINGUNITTYPESTR
	,(
		CAST((
				SELECT Name
				FROM synapse_fo.OMTeamMembershipCriterion
				WHERE OMTeamMembershipCriterion.RecId = T1.TeamMembershipCriterion
				) AS NVARCHAR(60))
		) AS TEAMTYPE
	,(CAST((1) AS INT)) AS SAVEPERSONNAME
	,(
		CAST((
				SELECT TOP 1 LL.LOCATIONID
				FROM synapse_fo.LOGISTICSELECTRONICADDRESS LEA
				JOIN synapse_fo.LOGISTICSLOCATION LL ON LL.RECID = LEA.LOCATION
				WHERE LEA.RECID IN (
						T2.RECID
						,T3.RECID
						,T4.RECID
						,T5.RECID
						,T6.RECID
						,T7.RECID
						,T8.RECID
						,T9.RECID
						)
					AND LL.PARTITION = LEA.PARTITION
					AND LL.PARTITION = T1.PARTITION
				ORDER BY LL.LOCATIONID DESC
				) AS NVARCHAR(40))
		) AS ELECTRONICLOCATIONID
	,(CAST((1) AS INT)) AS REMOVEELECTRONICADDRESSESONDELETE
FROM synapse_fo.DIRPARTYTABLE T1
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T2 ON (
		(
			(T1.PRIMARYCONTACTEMAIL = T2.RECID)
			AND (T1.PARTITION = T2.PARTITION)
			)
		AND (T2.ISPRIMARY = 1)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T3 ON (
		(T1.PRIMARYCONTACTFAX = T3.RECID)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T4 ON (
		(T1.PRIMARYCONTACTPHONE = T4.RECID)
		AND (T1.PARTITION = T4.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T5 ON (
		(T1.PRIMARYCONTACTTELEX = T5.RECID)
		AND (T1.PARTITION = T5.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T6 ON (
		(T1.PRIMARYCONTACTURL = T6.RECID)
		AND (T1.PARTITION = T6.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T7 ON (
		(
			(T1.PRIMARYCONTACTFACEBOOK = T7.RECID)
			AND (T1.PARTITION = T7.PARTITION)
			)
		AND (T7.ISPRIMARY = 1)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T8 ON (
		(T1.PRIMARYCONTACTTWITTER = T8.RECID)
		AND (T1.PARTITION = T8.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.LOGISTICSELECTRONICADDRESS T9 ON (
		(T1.PRIMARYCONTACTLINKEDIN = T9.RECID)
		AND (T1.PARTITION = T9.PARTITION)
		)
LEFT OUTER JOIN synapse_fo.DIRPARTYTABLE T10 ON (
		(
			(T1.RECID = T10.RECID)
			AND (T1.PARTITION = T10.PARTITION)
			)
		AND T10.INSTANCERELATIONTYPE IN (10643)
		)
LEFT OUTER JOIN synapse_fo.DIRPARTYLOCATION T11 ON (
		(
			(T1.PRIMARYADDRESSLOCATION = T11.LOCATION)
			AND (T1.PARTITION = T11.PARTITION)
			)
		AND (
			(T1.RECID = T11.PARTY)
			AND (T1.PARTITION = T11.PARTITION)
			)
		)
LEFT OUTER JOIN synapse_fo.DIRPARTYTABLE T12 ON (
		(
			(T1.RECID = T12.RECID)
			AND (T1.PARTITION = T12.PARTITION)
			)
		AND T12.INSTANCERELATIONTYPE IN (
			16758
			,1209
			,6105
			,11000
			,17209
			,21198
			)
		)
LEFT OUTER JOIN synapse_fo.DIRNAMEAFFIX T13 ON (
		(
			(T10.PERSONALSUFFIX = T13.RECID)
			AND (T10.PARTITION = T13.PARTITION)
			)
		AND (T13.AFFIXTYPE = 2)
		)
LEFT OUTER JOIN synapse_fo.DIRNAMEAFFIX T14 ON (
		(
			(T10.PERSONALTITLE = T14.RECID)
			AND (T10.PARTITION = T14.PARTITION)
			)
		AND (T14.AFFIXTYPE = 1)
		)
LEFT OUTER JOIN synapse_fo.DIRPERSONNAME T15 ON (
		(
			(T10.RECID = T15.PERSON)
			AND (T10.PARTITION = T15.PARTITION)
			)
		AND (
			(
				T15.VALIDFROM <= GETUTCDATE()
				)
			AND (
				T15.VALIDTO >= GETUTCDATE()
				)
			)
		)
LEFT OUTER JOIN synapse_fo.DIRDUNSNUMBER T16 ON (
		(T12.DUNSNUMBERRECID = T16.RECID)
		AND (T12.PARTITION = T16.PARTITION)
		)
